def solve(rows):
    # Filter rows with unit_price below 169
    filtered_rows = [row for row in rows if row["unit_price"] < 169]

    # Extract day and order_id for sorting
    days = [row["day"] for row in filtered_rows]
    order_ids = [row["order_id"] for row in filtered_rows]

    # Initialize balance and tracking variables
    balance = 0
    min_balance = float('inf')
    first_day = None

    # Sort rows by (day, order_id) ascending
    sorted_rows = sorted(filtered_rows, key=lambda x: (x["day"], x["order_id"]))

    # Process each row
    for row in sorted_rows:
        if row["status"] in ("cancelled", "delayed"):
            if row["status"] == "cancelled":
                balance += row["quantity"]
            else:
                balance -= row["quantity"]

            if balance < min_balance:
                min_balance = balance
                first_day = row["day"]
            elif balance == min_balance:
                if first_day is None or row["day"] < first_day:
                    first_day = row["day"]

    # Return the result
    if min_balance != float('inf'):
        return [min_balance, first_day]
    else:
        return [0, None]
