def solve(rows):
    # Filter rows with region 'south' or 'west'
    filtered_rows = [row for row in rows if row["region"] in ("south", "west")]

    # Sort by unit_price descending, day ascending, order_id ascending
    sorted_rows = sorted(filtered_rows, key=lambda x: (-x["unit_price"], x["day"], x["order_id"]))

    # Extract product and quantity
    product_quantities = {}
    for row in sorted_rows:
        product = row["product"]
        quantity = row["quantity"]
        if product in product_quantities:
            product_quantities[product].append(quantity)
        else:
            product_quantities[product] = [quantity]

    # Calculate median for each product
    result = {}
    for product, quantities in product_quantities.items():
        if len(quantities) == 0:
            continue
        quantities.sort()
        n = len(quantities)
        if n % 2 == 1:
            median = quantities[n // 2]
        else:
            median = (quantities[n // 2 - 1] + quantities[n // 2]) / 2
        # Round to one decimal place
        rounded_median = round(median, 1)
        result[product] = rounded_median

    return result
```

