def solve(rows):
    # Filter rows with unit_price below 146
    filtered_rows = [row for row in rows if row.get('unit_price') < 146]

    # Group by region and calculate delivered percentage
    region_data = {}
    for row in filtered_rows:
        region = row.get('region')
        status = row.get('status')
        if region not in region_data:
            region_data[region] = {'total': 0, 'delivered': 0}
        region_data[region]['total'] += 1
        if status == 'delivered':
            region_data[region]['delivered'] += 1

    # Calculate percentages and filter by percentage >= 25
    result = []
    for region, data in region_data.items():
        count = data['delivered']
        total = data['total']
        percentage = round(100 * count / total, 1) if total > 0 else 0
        if percentage >= 25:
            result.append([region, percentage])

    # Sort by percentage descending and then value ascending
    result.sort(key=lambda x: (-x[1], x[0]))

    return result
```

