def solve(rows):
    filtered_rows = [row for row in rows if row['region'] in ['east', 'north'] and row['day'] <= 23]
    if not filtered_rows:
        return None
    region_sums = {}
    for row in filtered_rows:
        region = row['region']
        quantity = row['quantity']
        unit_price = row['unit_price']
        region_sums[region] = region_sums.get(region, 0) + quantity * unit_price
    if not region_sums:
        return None
    max_sum = max(region_sums.values())
    candidates = [region for region, total in region_sums.items() if total == max_sum]
    return min(candidates)
