def solve(rows):
    east_north_rows = [row for row in rows if row['region'] in ['east', 'north'] and row['day'] <= 23]
    if not east_north_rows:
        return None
    # Group by region and compute sum of quantity * unit_price
    region_sum = {}
    for row in east_north_rows:
        region = row['region']
        total = row['quantity'] * row['unit_price']
        if region in region_sum:
            region_sum[region] += total
        else:
            region_sum[region] = total
    # Find the region with the largest sum, and alphabetically smallest if tied
    max_sum = max(region_sum.values())
    candidates = [region for region, sum_val in region_sum.items() if sum_val == max_sum]
    candidates.sort()
    return candidates[0] if candidates else None
