def solve(rows):
    if not rows:
        return [0, None]

    # Extract distinct day values
    days = set(row["day"] for row in rows if row["status"] == "delayed")

    # Find the longest run of consecutive integers in days
    max_run = 1
    current_run = 1
    start_of_run = list(days)[0]

    for day in sorted(days):
        if day == start_of_run + current_run - 1:
            current_run += 1
        else:
            if current_run > max_run:
                max_run = current_run
                start_of_run = day
            current_run = 1

    if current_run > max_run:
        max_run = current_run
        start_of_run = list(days)[0]

    return [len(days), start_of_run]
