            balance += row["quantity"]
        elif row["status"] == "delayed":
            balance -= row["quantity"]

        if balance < min_balance:
            min_balance = balance
            first_day = row["day"]
        elif balance == min_balance:
            if first_day is None:
                first_day = row["day"]

    if min_balance != float('inf'):
        result = [min_balance, first_day]
    else:
        result = [0, None]

    return result
