def solve(rows):
    from collections import defaultdict

    # Group rows by region
    region_groups = defaultdict(list)
    for row in rows:
        region_groups[row["region"]].append(row)

    # Count delivered rows in each region
    region_counts = {}
    for region, group in region_groups.items():
        count = 0
        for row in group:
            if row["status"] == "delivered":
                count += 1
        region_counts[region] = (count, len(group))

    # Prepare results
    results = []
    for region, (count, group_size) in region_counts.items():
        if group_size == 0:
            continue
        percentage = round(100 * count / group_size, 1)
        if percentage >= 35:
            results.append((percentage, region))

    # Sort by percentage descending, then value ascending
    results.sort(key=lambda x: (-x[0], x[1]))

    return results
```

