    for row in rows:
        if row['quantity'] >= 3:
            day_set.add(row['day'])
    if not day_set:
        return [0, None]
    sorted_days = sorted(day_set)
    max_length = 0
    start = sorted_days[0]
    current_length = 1
    for i in range(1, len(sorted_days)):
        if sorted_days[i] == sorted_days[i - 1] + 1:
            current_length += 1
        else:
            if current_length > max_length:
                max_length = current_length
                start = sorted_days[i - 1] - current_length + 1
            current_length = 1
    if current_length > max_length:
        max_length = current_length
        start = sorted_days[-1] - current_length + 1
    return [max_length, start]
