def solve(rows):
    from collections import defaultdict

    region_data = defaultdict(lambda: {"total": 0, "cancelled": 0})

    for row in rows:
        if row["region"] in ["north", "west"]:
            region_data[row["region"]]["total"] += 1
            if row["status"] == "cancelled":
                region_data[row["region"]]["cancelled"] += 1

    result = []
    for region, data in region_data.items():
        total = data["total"]
        cancelled = data["cancelled"]
        if total == 0:
            continue
        percentage = round(100 * cancelled / total, 1)
        if percentage >= 30:
            result.append((region, percentage))

    # Sort by percentage descending, then by value ascending
    result.sort(key=lambda x: (-x[1], x[0]))
    return result
