def solve(rows):
    # Count the number of rows for each region
    region_count = {}
    for row in rows:
        if row["region"] in ["north", "west"]:
            region_count[row["region"]] = region_count.get(row["region"], 0) + 1

    # Calculate the number of cancelled orders for each region
    cancelled_count = {}
    for row in rows:
        if row["region"] in ["north", "west"]:
            cancelled_count[row["region"]] = cancelled_count.get(row["region"], 0) + (1 if row["status"] == "cancelled" else 0)

    # Calculate the percentage for each region
    percentage = {}
    for region in region_count:
        count = region_count[region]
        cancelled = cancelled_count[region]
        percentage[region] = round(100 * cancelled / count, 1)

    # Filter regions with percentage >= 30
    filtered = [region for region in percentage if percentage[region] >= 30]

    # Sort by percentage descending and then value ascending
    sorted_filtered = sorted(filtered, key=lambda x: (-percentage[x], x))

    # Prepare the result
    result = []
    for region in sorted_filtered:
        result.append((region, percentage[region]))

    return result
```

